import React, { useState } from 'react';
import { LayoutDashboard, TrendingUp, FileCog, Plug, Settings, AlertTriangle, ChevronRight, CheckCircle2, DollarSign, User, Banknote } from 'lucide-react';

// --- Mock Data --- //
const initialForecastData = [65, 70, 75, 80, 78, 85, 90, 88, 60, 45, 50, 55, 65, 70];
const resolvedForecastData = [65, 70, 75, 80, 78, 85, 90, 88, 60, 75, 80, 85, 95, 100];
const forecastLabels = ['Today', 'Wk1', 'Wk2', 'Wk3', 'Wk4', 'Wk5', 'Wk6', 'Wk7', 'Wk8', 'Wk9', 'Wk10', 'Wk11', 'Wk12', 'Wk13'];

const Sidebar = ({ currentScreen, setCurrentScreen }) => {
  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'forecast', label: 'Cash Flow Forecast', icon: TrendingUp },
    { id: 'scenarios', label: 'Scenario Modeling', icon: FileCog },
    { id: 'integrations', label: 'Integrations', icon: Plug },
    { id: 'settings', label: 'Settings', icon: Settings },
  ];

  return (
    <div className="w-64 bg-[#1a365d] text-white flex flex-col">
      <div className="p-6 text-2xl font-bold border-b border-white/20">CashFlow<span className="text-blue-300">Pro</span></div>
      <nav className="flex-1 p-4 space-y-2">
        {navItems.map(item => (
          <a
            key={item.id}
            href="#"
            onClick={(e) => { e.preventDefault(); setCurrentScreen(item.id); }}
            className={`flex items-center px-4 py-2.5 rounded-md text-sm font-medium transition-all duration-200 ${currentScreen === item.id ? 'bg-blue-700/50 text-white' : 'text-blue-100 hover:bg-blue-700/30 hover:text-white'}`}>
            <item.icon className="w-5 h-5 mr-3" />
            {item.label}
          </a>
        ))}
      </nav>
      <div className="p-4 border-t border-white/20">
          <div className="flex items-center">
              <div className="w-10 h-10 rounded-full bg-blue-300 flex items-center justify-center font-bold text-[#1a365d]">AS</div>
              <div className="ml-3">
                  <p className="text-sm font-semibold">Aisha Sharma</p>
                  <p className="text-xs text-blue-200">Precision Parts Mfg.</p>
              </div>
          </div>
      </div>
    </div>
  );
};

const DashboardScreen = ({ setCurrentScreen }) => (
  <div className="space-y-6">
    <h1 className="text-2xl font-bold text-gray-800">Dashboard</h1>
    <div onClick={() => setCurrentScreen('forecast')} className="cursor-pointer group flex items-center p-4 bg-red-100 border-l-4 border-red-500 rounded-md shadow-sm hover:shadow-md transition-all duration-200">
      <AlertTriangle className="w-8 h-8 text-red-600 mr-4" />
      <div>
        <h2 className="text-lg font-semibold text-red-800">Potential Cash Shortfall Alert</h2>
        <p className="text-sm text-red-700">Our AI model projects a potential cash shortfall of <span className="font-bold">$47,250</span> in approximately 5 weeks. Click to review the forecast.</p>
      </div>
      <ChevronRight className="w-6 h-6 text-red-500 ml-auto group-hover:translate-x-1 transition-transform"/>
    </div>
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="p-6 bg-white rounded-lg shadow-sm border border-gray-200">
            <div className="flex items-center"><Banknote className="w-6 h-6 text-gray-500 mr-3"/><h3 className="text-lg font-semibold text-gray-700">Total Cash Balance</h3></div>
            <p className="text-3xl font-bold text-gray-900 mt-2">$1,245,670.18</p>
            <p className="text-sm text-green-600 mt-1">+2.1% from last month</p>
        </div>
        <div className="p-6 bg-white rounded-lg shadow-sm border border-gray-200">
            <div className="flex items-center"><DollarSign className="w-6 h-6 text-gray-500 mr-3"/><h3 className="text-lg font-semibold text-gray-700">Accounts Receivable</h3></div>
            <p className="text-3xl font-bold text-gray-900 mt-2">$312,890.50</p>
            <p className="text-sm text-gray-500 mt-1">Avg. 28 days to collect</p>
        </div>
        <div className="p-6 bg-white rounded-lg shadow-sm border border-gray-200">
            <div className="flex items-center"><User className="w-6 h-6 text-gray-500 mr-3"/><h3 className="text-lg font-semibold text-gray-700">Accounts Payable</h3></div>
            <p className="text-3xl font-bold text-gray-900 mt-2">$188,430.75</p>
            <p className="text-sm text-gray-500 mt-1">Due within 30 days</p>
        </div>
    </div>
  </div>
);

const ForecastChart = ({ data, isResolved }) => (
    <div className="p-6 bg-white rounded-lg shadow-sm border border-gray-200">
        <div className="flex justify-between items-center mb-4">
            <div>
                <h3 className="text-lg font-semibold text-gray-800">90-Day Cash Flow Forecast</h3>
                <p className="text-sm text-gray-500">Projected cash balance (in thousands)</p>
            </div>
            {isResolved && <div className="px-3 py-1 bg-green-100 text-green-800 text-sm font-semibold rounded-full flex items-center"><CheckCircle2 className="w-4 h-4 mr-2"/>Shortfall Resolved</div>}
        </div>
        <div className="h-64 flex items-end justify-between space-x-2">
            {data.map((value, index) => {
                const isDip = !isResolved && index >= 8 && index <= 10;
                const barColor = isResolved ? 'bg-blue-400' : isDip ? 'bg-red-400' : 'bg-blue-400';
                return (
                    <div key={index} className="flex-1 flex flex-col items-center">
                        <div className={`w-full rounded-t-sm transition-all duration-300 ${barColor} hover:bg-blue-500`} style={{ height: `${value}%` }}></div>
                        <span className="text-xs text-gray-500 mt-2">{forecastLabels[index]}</span>
                    </div>
                )
            })}
        </div>
        <div className="w-full border-t border-dashed border-red-500 mt-[-80px] relative">
            <span className="absolute left-0 -top-3 text-xs text-red-600 bg-white px-1">Min. Buffer ($50k)</span>
        </div>
    </div>
);

const ForecastScreen = ({ setCurrentScreen, scenarioApplied }) => (
    <div className="space-y-6">
        <h1 className="text-2xl font-bold text-gray-800">Cash Flow Forecast</h1>
        <ForecastChart data={scenarioApplied ? resolvedForecastData : initialForecastData} isResolved={scenarioApplied} />
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="p-6 bg-white rounded-lg shadow-sm border border-gray-200">
                <h3 className="text-lg font-semibold text-gray-700 mb-3">Key Insights</h3>
                <ul className="space-y-2 text-sm text-gray-600">
                    <li className={`flex items-start ${scenarioApplied ? 'text-green-700' : 'text-red-700'}`}>
                        <AlertTriangle className={`w-4 h-4 mr-2 mt-0.5 flex-shrink-0 ${scenarioApplied ? 'hidden' : ''}`} />
                        <CheckCircle2 className={`w-4 h-4 mr-2 mt-0.5 flex-shrink-0 ${scenarioApplied ? '' : 'hidden'}`} />
                        <span>{scenarioApplied ? 'Projected cash balance remains above minimum buffer.' : 'Projected to drop below $50k minimum buffer in Week 9.'}</span>
                    </li>
                    <li className="flex items-start"><ChevronRight className="w-4 h-4 mr-2 mt-0.5 text-gray-400 flex-shrink-0"/><span>Large supplier payment of $120,000 to Aus-Steel due in Week 8 is the primary driver.</span></li>
                </ul>
            </div>
            <div className="p-6 bg-white rounded-lg shadow-sm border border-gray-200 flex flex-col justify-center items-center">
                <h3 className="text-lg font-semibold text-gray-700">Need to mitigate this shortfall?</h3>
                <p className="text-sm text-gray-500 mt-1 mb-4">Model a scenario to see the impact of your decisions.</p>
                <button onClick={() => setCurrentScreen('scenarios')} className="px-6 py-2 bg-[#2563eb] text-white font-semibold rounded-lg shadow-sm hover:bg-blue-700 transition-all duration-200">
                    Model a New Scenario
                </button>
            </div>
        </div>
    </div>
);

const ScenarioScreen = ({ setCurrentScreen, setScenarioApplied }) => (
    <div className="space-y-6">
        <h1 className="text-2xl font-bold text-gray-800">Model a New Scenario</h1>
        <div className="p-8 bg-white rounded-lg shadow-sm border border-gray-200 max-w-2xl mx-auto">
            <h2 className="text-lg font-semibold text-gray-800">Create Scenario: Mitigate Shortfall</h2>
            <p className="text-sm text-gray-500 mt-1 mb-6">Test the impact of a business decision on your cash flow forecast.</p>
            <div className="space-y-4">
                <div>
                    <label htmlFor="actionType" className="block text-sm font-medium text-gray-700">Action Type</label>
                    <select id="actionType" className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm rounded-md">
                        <option>Delay a payment</option>
                        <option>Expedite an invoice payment</option>
                        <option>Draw on line of credit</option>
                    </select>
                </div>
                <div>
                    <label htmlFor="payee" className="block text-sm font-medium text-gray-700">Supplier / Payee</label>
                    <input type="text" id="payee" defaultValue="Aus-Steel Suppliers" className="mt-1 block w-full pl-3 py-2 text-base border-gray-300 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm rounded-md bg-gray-100" readOnly/>
                </div>
                <div>
                    <label htmlFor="delay" className="block text-sm font-medium text-gray-700">Delay Payment By</label>
                    <select id="delay" className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm rounded-md">
                        <option>7 days</option>
                        <option selected>14 days</option>
                        <option>21 days</option>
                        <option>30 days</option>
                    </select>
                </div>
                <div className="pt-4 flex justify-end">
                    <button 
                        onClick={() => {
                            setScenarioApplied(true);
                            setCurrentScreen('confirmation');
                        }}
                        className="w-full md:w-auto px-8 py-2.5 bg-[#166534] text-white font-semibold rounded-lg shadow-sm hover:bg-green-800 transition-all duration-200">
                        Run Scenario & Update Forecast
                    </button>
                </div>
            </div>
        </div>
    </div>
);

const ConfirmationScreen = ({ setCurrentScreen, setScenarioApplied }) => (
    <div className="space-y-6">
        <h1 className="text-2xl font-bold text-gray-800">Scenario Result</h1>
        <div className="p-6 bg-green-50 border-l-4 border-green-500 rounded-md">
            <div className="flex items-center">
                <CheckCircle2 className="w-8 h-8 text-green-600 mr-4" />
                <div>
                    <h2 className="text-lg font-semibold text-green-800">Aha! Scenario Successful</h2>
                    <p className="text-sm text-green-700">Delaying the payment to Aus-Steel Suppliers by 14 days has resolved the projected cash shortfall.</p>
                </div>
            </div>
        </div>
        <ForecastChart data={resolvedForecastData} isResolved={true} />
        <div className="flex justify-center space-x-4 pt-4">
             <button onClick={() => { setScenarioApplied(false); setCurrentScreen('dashboard'); }} className="px-6 py-2 bg-gray-200 text-gray-800 font-semibold rounded-lg hover:bg-gray-300 transition-all duration-200">
                Return to Dashboard
            </button>
            <button onClick={() => setCurrentScreen('scenarios')} className="px-6 py-2 bg-[#2563eb] text-white font-semibold rounded-lg shadow-sm hover:bg-blue-700 transition-all duration-200">
                Model Another Scenario
            </button>
        </div>
    </div>
);


export default function CashflowProPrototype() {
  const [currentScreen, setCurrentScreen] = useState('dashboard');
  const [scenarioApplied, setScenarioApplied] = useState(false);

  const renderScreen = () => {
    switch (currentScreen) {
      case 'dashboard':
        return <DashboardScreen setCurrentScreen={setCurrentScreen} />;
      case 'forecast':
        return <ForecastScreen setCurrentScreen={setCurrentScreen} scenarioApplied={scenarioApplied} />;
      case 'scenarios':
        return <ScenarioScreen setCurrentScreen={setCurrentScreen} setScenarioApplied={setScenarioApplied} />;
      case 'confirmation':
        return <ConfirmationScreen setCurrentScreen={setCurrentScreen} setScenarioApplied={setScenarioApplied} />;
      // Add placeholders for other screens
      case 'integrations':
      case 'settings':
        return <div className="p-8"><h1 className="text-2xl font-bold text-gray-800">{currentScreen.charAt(0).toUpperCase() + currentScreen.slice(1)}</h1><p className="text-gray-600 mt-4">This screen is a placeholder for the prototype.</p></div>;
      default:
        return <DashboardScreen setCurrentScreen={setCurrentScreen} />;
    }
  };

  return (
    <div className="flex h-screen bg-gray-100 font-sans antialiased" style={{ fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <Sidebar currentScreen={currentScreen} setCurrentScreen={setCurrentScreen} />
      <main className="flex-1 p-8 overflow-y-auto">
        <div className="max-w-7xl mx-auto">
          {renderScreen()}
        </div>
      </main>
    </div>
  );
}

